    [4915]={name="Soft Wool Boots",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Cutting Teeth' - pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Cutting Teeth",lore="The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."},
    [4916]={name="Soft Wool Vest",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Sarkoth' - pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Sarkoth",lore="Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."},
    [4919]={name="Soft Wool Belt",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Sting of the Scorpid' - pick it over the other choices. In Valley of Trials.",zone="Valley of Trials",questName="Sting of the Scorpid",lore="Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."},
    [4936]={name="Dirt-trodden Boots",quality=1,ilvl=8,sourceType="quest_reward",instructions="Reward from the quest 'From The Wreckage....' - pick it over the other choices. In Durotar.",zone="Durotar",questName="From The Wreckage....",lore="One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."},
