    [5241]={name="Dwarven Flamestick",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Gathering Idols' - pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="Gathering Idols",lore="Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"},
    [5242]={name="Cinder Wand",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Arugal's Folly' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Arugal's Folly",lore="As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."},
    [5243]={name="Firebelcher",quality=3,ilvl=20,reqLevel=15,sourceType="boss_drop",instructions="Drops from Deviate Faerie Dragon in Wailing Caverns.",zone="Wailing Caverns",npc="Deviate Faerie Dragon"},
    [5245]={name="Summoner's Wand",quality=2,ilvl=34,reqLevel=29,sourceType="world_drop",instructions="Drops from Dalaran Summoner in Dalaran.",zone="Dalaran",npc="Dalaran Summoner"},
    [5246]={name="Excavation Rod",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Ormer's Revenge' - pick it over the other choices. In Wetlands.",zone="Wetlands",questName="Ormer's Revenge",lore="While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."},
    [5250]={name="Charred Wand",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Dangerous!' - pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Dangerous!",lore="Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."},
    [5274]={name="Rose Mantle",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Morganth'. In Redridge Mountains.",zone="Redridge Mountains",questName="Morganth",lore="After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."},
    [5310]={name="Sea Dog Britches",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'The Guns of Northwatch' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Guns of Northwatch",lore="Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."},
    [5326]={name="Flaring Baton",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Escape' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Escape",lore="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"},
    [5340]={name="Cauldron Stirrer",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Apothecary Zamah'. In The Barrens.",zone="The Barrens",questName="Apothecary Zamah",lore="I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."},
    [5356]={name="Branding Rod",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Isha Awak' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Isha Awak",lore="The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."},
    [5444]={name="Miner's Cape",quality=3,ilvl=19,reqLevel=14,sourceType="boss_drop",instructions="Drops from Miner Johnson in The Deadmines.",zone="The Deadmines",npc="Miner Johnson"},
    [5542]={name="Pearl-clasped Cloak",quality=2,ilvl=19,reqLevel=14,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring"},
    [5591]={name="Rain-spotted Cape",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'The Enchanted Glade' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5604]={name="Elven Wand",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
    [5606]={name="Gardening Gloves",quality=1,ilvl=9,sourceType="quest_reward",instructions="Reward from the quest 'Timberling Sprouts' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Timberling Sprouts",lore="Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."},
    [5611]={name="Tear of Grief",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'For Love Eternal'. In Darkshore.",zone="Darkshore",questName="For Love Eternal",lore="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."},
    [5767]={name="Violet Robes",quality=1,ilvl=9,reqLevel=4,sourceType="world_drop",instructions="Drops from Frostmane Seer in Kharanos.",zone="Kharanos",npc="Frostmane Seer"},
