    [6060]={name="Flax Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Damned' - pick it over the other choices. In Deathknell.",zone="Deathknell",questName="The Damned",lore="My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."},
    [6173]={name="Snow Boots",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'A New Threat' - pick it over the other choices. In Coldridge Valley.",zone="Coldridge Valley",questName="A New Threat",lore="I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."},
    [6191]={name="Kimbra Boots",quality=2,ilvl=23,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Chok'sul' - pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="WANTED: Chok'sul",lore="By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."},
