    [6482]={name="Firewalker Boots",quality=2,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'Elixir of Pain' - pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Elixir of Pain",lore="Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."},
    [6505]={name="Crescent Staff",quality=3,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'Leaders of the Fang' - pick it over the other choices. In Wailing Caverns.",zone="Wailing Caverns",questName="Leaders of the Fang",lore="The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."},
