    [6898]={name="Orb of Soran'ruk",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'The Orb of Soran'ruk' - pick it over the other choices.",questName="The Orb of Soran'ruk",lore="Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps.",proc="Use: Restores 25 health every 3 sec for 30 sec. (30 Min Cooldown)"},
