    [15106]={name="Staff of Dar'Orahil",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'The Completed Orb of Dar'Orahil' - pick it over the other choices.",questName="The Completed Orb of Dar'Orahil",lore="I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb."},
    [15108]={name="Orb of Dar'Orahil",quality=3,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'The Completed Orb of Dar'Orahil' - pick it over the other choices.",questName="The Completed Orb of Dar'Orahil",lore="I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb.",proc="Use: Restores 40 health every 3 sec for 30 sec. (30 Min Cooldown)"},
    [15109]={name="Staff of Soran'ruk",quality=2,ilvl=25,sourceType="quest_reward",instructions="Reward from the quest 'The Orb of Soran'ruk' - pick it over the other choices.",questName="The Orb of Soran'ruk",lore="Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps."},
    [15397]={name="Oakthrush Staff",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'The Fragments Within' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="The Fragments Within",lore="The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."},
    [15444]={name="Staff of Orgrimmar",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
