    [20530]={name="Robes of Servitude",quality=3,ilvl=52,sourceType="quest_reward",instructions="Reward from the quest 'Trolls of a Feather' - pick it over the other choices.",questName="Trolls of a Feather",lore="My pet is almost done. Now I just need something to stuff it with. Only the voodoo feathers from the trolls in the sunken temple will do. They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro."},
