    [21186]={name="Rockfury Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear' - pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21335]={name="Doomcaller's Mantle",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Doomcaller's Mantle'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Doomcaller's Mantle",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21337]={name="Doomcaller's Circlet",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Doomcaller's Circlet'. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Doomcaller's Circlet",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21461]={name="Leggings of the Black Blizzard",quality=4,ilvl=72,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
